SELECT rel.PRODID prodid, rel.PROD_NAME prodName, rel.REP_TYPE repType, rfp.NAME repTypeName, rel.REP_NAME repName, CASE WHEN rel.START_DATE IS NULL OR rel.START_DATE = rel.END_DATE THEN DATE_FORMAT(rel.END_DATE,'%Y-%m-%d') ELSE CONCAT_WS( '',DATE_FORMAT(rel.START_DATE,'%Y-%m-%d') , '--',DATE_FORMAT(rel.END_DATE,'%Y-%m-%d')) END reportDate, rel.REVEAL_END_DATE revealEndDate, rj.JOB_NAME jobName FROM REP_EXPECTED_LOG rel LEFT JOIN REP_JOB rj ON rel.JOB_ID = rj.JOB_ID LEFT JOIN REP_INFO ri ON rel.REP_ID = ri.REP_ID LEFT JOIN REP_FTP_PATH rfp ON ri.REPORT_CATEGORY = rfp.ID WHERE rel.STATUS = #{status,jdbcType=VARCHAR}
AND DATE_FORMAT(rel.REVEAL_END_DATE,'%Y-%m-%d') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(rel.REVEAL_END_DATE,'%Y-%m-%d') <= #{revealEndDateEnd,jdbcType=VARCHAR}
AND rel.REP_NAME like concat(concat('%',#{repName,jdbcType=VARCHAR}),'%')
AND rel.PRODID IN
#{item}
AND rel.JOB_ID in
#{item}
AND ri.REPORT_CATEGORY IN
#{item}
